/**
 * Autogenerated OpenAPI documentation.
 *
 * Built from the same discovery result as the routes, so the spec can never
 * drift from the served endpoints. Served as JSON at `/openapi.json` and
 * rendered by Swagger UI at `/docs`.
 */
import type { FnDoc } from "./fn-docs.js";

/** Render a library TSDoc entry as OpenAPI operation description markdown. */
export function docDescription(name: string, doc: FnDoc | undefined): string {
  if (!doc) return `Call the \`${name}\` library function.`;
  const parts = [doc.description];
  if (doc.params.length > 0) {
    parts.push(
      "Positional `args` array, in order:\n" +
        doc.params.map((p) => `- \`${p.name}\`${p.description ? `: ${p.description}` : ""}`).join("\n"),
    );
  }
  if (doc.returns) parts.push(`Returns: ${doc.returns}`);
  return parts.filter(Boolean).join("\n\n");
}

export function buildOpenApi(
  functionNames: string[],
  meta: { title: string; version: string },
  docs: Record<string, FnDoc> = {},
  groups: Record<string, string> = {},
  opts: { flat?: boolean } = {},
): Record<string, unknown> {
  const errorEnvelope = {
    type: "object",
    required: ["error"],
    properties: {
      error: {
        type: "object",
        required: ["code", "message"],
        properties: {
          code: { type: "string" },
          message: { type: "string" },
        },
      },
    },
  };
  const resultEnvelope = {
    type: "object",
    required: ["result"],
    properties: {
      // Library outputs are commonly TS objects/arrays/primitives.
      result: { description: "The function's return value, as JSON." },
    },
  };
  const argsBody = {
    required: true,
    content: {
      "application/json": {
        schema: {
          type: "object",
          required: ["args"],
          properties: {
            args: {
              type: "array",
              description: "Positional arguments, forwarded as fn(...args).",
            },
          },
        },
      },
    },
  };

  const functionPaths: Record<string, unknown> = {};
  for (const name of functionNames) {
    const doc = docs[name];
    const summary = doc?.description.split("\n")[0] || `Call ${name}`;
    const operation = {
      operationId: name,
      summary,
      description: docDescription(name, doc),
      requestBody: argsBody,
      responses: {
        "200": {
          description: "Function result.",
          content: { "application/json": { schema: resultEnvelope } },
        },
        "400": { description: "Invalid body.", content: { "application/json": { schema: errorEnvelope } } },
        "404": { description: "Unknown function.", content: { "application/json": { schema: errorEnvelope } } },
        "413": { description: "Body exceeds the size limit.", content: { "application/json": { schema: errorEnvelope } } },
        "500": {
          description: "The function threw, or its result is not JSON-serializable.",
          content: { "application/json": { schema: errorEnvelope } },
        },
      },
    };
    if (opts.flat !== false) functionPaths[`/api/${name}`] = { post: operation };
    // Grouped subpath alias, e.g. /api/io/fromPOSCAR.
    if (groups[name]) {
      functionPaths[`/api/${groups[name]}/${name}`] = {
        post: { ...operation, operationId: `${groups[name]}_${name}` },
      };
    }
  }

  return {
    openapi: "3.1.0",
    info: {
      title: meta.title,
      version: meta.version,
      description:
        "Auto-exposed matsci-parse library functions. Each top-level function export is a POST /api/<functionName> endpoint.",
    },
    paths: {
      "/healthz": {
        get: {
          operationId: "health",
          summary: "Health check.",
          responses: {
            "200": {
              description: "Server status.",
              content: {
                "application/json": {
                  schema: {
                    type: "object",
                    properties: {
                      status: { type: "string" },
                      functions: { type: "integer" },
                    },
                  },
                },
              },
            },
          },
        },
      },
      "/api": {
        get: {
          operationId: "listFunctions",
          summary: "List exposed function names.",
          responses: {
            "200": {
              description: "Exposed functions.",
              content: {
                "application/json": {
                  schema: {
                    type: "object",
                    properties: { functions: { type: "array", items: { type: "string" } } },
                  },
                },
              },
            },
          },
        },
      },
      "/api/batch": {
        post: {
          operationId: "batch",
          summary: "Call many functions in one round trip.",
          requestBody: {
            required: true,
            content: {
              "application/json": {
                schema: {
                  type: "object",
                  required: ["calls"],
                  properties: {
                    calls: {
                      type: "array",
                      items: {
                        type: "object",
                        required: ["fn", "args"],
                        properties: {
                          fn: { type: "string" },
                          args: { type: "array" },
                        },
                      },
                    },
                  },
                },
              },
            },
          },
          responses: {
            "200": {
              description: "Per-item ok/error outcomes, in call order.",
              content: {
                "application/json": {
                  schema: {
                    type: "object",
                    properties: {
                      results: {
                        type: "array",
                        items: {
                          type: "object",
                          required: ["ok"],
                          properties: {
                            ok: { type: "boolean" },
                            result: {},
                            error: errorEnvelope["properties"]["error"],
                          },
                        },
                      },
                    },
                  },
                },
              },
            },
            "400": { description: "Invalid batch.", content: { "application/json": { schema: errorEnvelope } } },
          },
        },
      },
      ...functionPaths,
    },
  };
}
